INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('spooky-scary-spaces', 297440, '2022-07-05', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co82u5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scrwqn.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spooky Scary Spaces', 'Spooky Scary Spaces is a third-person adventure game, with a gameplay and visual style inspired by the survival horror games of the Playstation 1 and Playstation 2 era. In it, the player is a girl who, water pistol in hand, enters a house where other children are constantly disappearing. However, inside the house she observes that it does not follow a logical order, and each area seems to have no relation to the previous one. Even so, she advances through the house despite her fear, knowing that she is on the right path, as indicated by the presence of the Motogotchi (hand-held video game consoles) of the children who disappeared there earlier.' FROM games WHERE igdb_id = 297440 ON CONFLICT (game_id, language_code) DO NOTHING;
