INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Heart of Butterblue', 'It is under these circumstances that Phebe finds herself moving to the isolated frontier town of Edgeville. Rumors have it that monsters roam the lands after dark and anyone caught outside is never heard from again. With eerie murderous howling heard every night, Phebe has no choice to become accustomed to this new life if she wants to find her missing grandfather.' FROM games WHERE igdb_id = 225238 ON CONFLICT (game_id, language_code) DO NOTHING;
