INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blunderbubb!', 'You must take control of the Blunderbubb, the latest innovation in bubble-based defense technology, to shoot down the incoming deluge of colorful bubbles before you are completely overrun. Just hold down to aim, and release to launch. Connect three or more bubbles with matching colors to pop them and remove them from the field.' FROM games WHERE igdb_id = 210493 ON CONFLICT (game_id, language_code) DO NOTHING;
