INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cogen-sword-of-rewind-limited-edition', 172803, '2022-01-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4ehn.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scdt3u.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cogen: Sword of Rewind - Limited Edition', 'Rewind, rethink, redo. Cogen is a brand-new kind of 2D action game where there''s no time for death. Any hit you take is a death sentence in this side-scrolling 2D action game. But fear not! You may lack the HP to weather a beating, but you''ve got the Ouroboros System on your side. This futuristic technology kicks in the instant death embraces you and allows you to rewind up to 3 seconds of time. Slip up and wish you could take it back? Want to play around and experiment? Easy, just rewind the clock! Hone your skills through trial and error, and triumph over diabolical traps and legions of fearsome foes!
