INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ticky''s Wake Up Call', 'In Ticky''s Wake Up Call, you play as Ticky, the walking, talking alarm clock! Ticky has a very important job to do, and it''s up to you to make sure he does it on time! Dodge traps and solve dangerous situations all while trying to beat the game as fast as possible!' FROM games WHERE igdb_id = 323600 ON CONFLICT (game_id, language_code) DO NOTHING;
