INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('stellaris-console-edition-the-royal', 198396, '2022-07-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4ows.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stellaris: Console Edition - The Royal', 'Explore different stars, get acquainted with a wide variety of races, and deepen interaction. Dispatch research vessels, construction vessels, and sometimes warships to build a giant galactic empire. Each of your actions will determine the fate of the entire galaxy and bring evolution, development, and conflict to the various races living in it. Like other large-scale strategy games, this game will evolve over time. With the active free updates that characterize Paradox games, you''ll always be able to keep your empire expanding with the latest technology and features.
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 198396 AND p.igdb_id = 48 ON CONFLICT DO NOTHING;
INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('rental-chan', 228823, '2022-12-08', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5w05.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3gq3.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rental Chan', 'Racheal works for an app called Rent-A-Friend. She gets paid for being friends with people for a limited time. She needs money to pay for her little sister''s hospital bills who is being treated for a rare disease. When a rare opportunity comes up, a family is worried about their daughter and is willing to pay Rachael a large sum of money to transfer schools and befriend with until the end of the school year.' FROM games WHERE igdb_id = 228823 ON CONFLICT (game_id, language_code) DO NOTHING;
