INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Autumn Romance', '这是个普通的故事，因为主角是个普通的阿宅，而情节是我们视而不见的日常；这是个值得怀念的故事，那是我们不会再有的时光。当平静到暗淡的大学生活因她们而掀起波澜，生活开始发生了变化。这是个氤氲着青涩懵懂的秋天，被时间和她们推着成长的你，会不会在多年以后感叹那些日子因为她们而灿烂。' FROM games WHERE igdb_id = 191039 ON CONFLICT (game_id, language_code) DO NOTHING;
