INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'KaRu', 'KaRu is a short, horror experience where you play as a Parasite. He wakes up next to a young boy he never met in a place they shouldn''t be. Now they have to trust each other and find a way out. The game is about an hour long, and it has four endings! This is meant as an introduction to many more insights to come, taking place within the same universe, so, please do enjoy this little world!' FROM games WHERE igdb_id = 195552 ON CONFLICT (game_id, language_code) DO NOTHING;
