INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WyndBlast', 'Wyndblast is a blockchain-based game built on the Avalanche network. Players can collect and battle unique NFT digital fighters, including assaulter, ranger, and vanguard classes, each with their own factions and rarity levels. The game features real-time battles and fast-paced gameplay, with the outcome determined by the statistics and abilities of the fighters that players bring to the battle.' FROM games WHERE igdb_id = 234752 ON CONFLICT (game_id, language_code) DO NOTHING;
