INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Square Valley', 'You play as the Spirit of the Valley, tasked with creating unique lands that meet the needs of the citizens. To achieve this, you will need to place tiles such as houses, trees, farms, animals, and much more! Each tile you position is unique in its characteristics and will be scored accordingly. You''ll also create roads, rivers, fences, and more to connect all your tiles together in a meaningful way.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 200051 AND ge.slug = 'puzzle' ON CONFLICT DO NOTHING;
