INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Freeze the Time', 'Freeze the time is a puzzle game with a 2D view. The goal of the game is to bring the character to the exit. When a button is pressed, the doors open. There are also saws on the levels that must be avoided. By holding down the left mouse button, you can control the movement of the level.' FROM games WHERE igdb_id = 187429 ON CONFLICT (game_id, language_code) DO NOTHING;
