INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Empire of Ember', 'Empire of Ember is an action RPG and strategy game. You play as a Lightbringer, a young wizard who just inherited rule over a destroyed city. You have to rebuild it to its former glory while you live adventures in first-person, dual-wielding steel and magic, exploring procedurally generated dungeons and leading your troops to clashes of up to 100 units. You can customize your city to its finest details with a 3D city-builder, and then upload it for other players to explore and siege.' FROM games WHERE igdb_id = 152510 ON CONFLICT (game_id, language_code) DO NOTHING;
