INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Six. Eight. Two.', 'SCP-682 has escaped its containment cell, MTF group was deployed to contain it. Use guns to severe its limbs and cease its movements or to slow it down. There are 2 control rooms, the first one is for security cameras and the other for Acid. Your goal is to contain SCP-682 by submerging it in Acid.' FROM games WHERE igdb_id = 281258 ON CONFLICT (game_id, language_code) DO NOTHING;
