INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Panty Load', 'Casual arcade gameplay with a twist! You want, no you need to get off. Can you avoid life''s obstacles for the ultimate reward. Get your load into your panty by any means necessary! Humorous in game achievements! Multiple visual endings not for the faint of heart! Don''t take life so seriously!' FROM games WHERE igdb_id = 204163 ON CONFLICT (game_id, language_code) DO NOTHING;
