INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Lizartian', 'The Lizartian is a top-down action-adventure game. We will embody a lizard tamer, a Lizartian, who will have to travel the vast lands of Dekoto to fulfill his revenge. Along the way, he''ll face dangers like savage bandits, rugged terrain, and the legendary sandstorm.' FROM games WHERE igdb_id = 202614 ON CONFLICT (game_id, language_code) DO NOTHING;
