INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Menseki Genius', 'That satisfying feeling that comes from solving a puzzle! Menseki Genius is a novel Japanese logic puzzle game that''s been attracting attention from around the world. This Genius version is a compilation of the most difficult puzzles included in Menseki: Area Maze Puzzles, for the most expert players. Find your way to the solution, deducing unknown lengths and areas from known lengths and areas. All you need is the "length x breadth = area" formula for calculating the area of a rectangle!' FROM games WHERE igdb_id = 192068 ON CONFLICT (game_id, language_code) DO NOTHING;
