INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Box Dash', 'Box Dash is a platform game that trains your concentration. In the game, you need to focus your attention to avoid obstacles and destroy as many monsters as possible to get stars. The game is divided into training mode, normal mode and extreme mode, with dozens of levels. It may be difficult to play the game at first, but once you get used to it, you will appreciate the fun.' FROM games WHERE igdb_id = 196272 ON CONFLICT (game_id, language_code) DO NOTHING;
