INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('busty-bunny-the-bounty-babe', 274869, '2022-01-13', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9h08.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scwggd.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Busty Bunny the Bounty Babe', 'You are Busty, a buxom bunny bounty babe, looking to nab the ultimate score, a gang boss named Fanny Fennec, leader of the Fanny Pack. You land your 57 star cruiser spacecraft on the outskirts of Delta city on the planet 6-9. instantly you can see evidence of the gang. Propaganda posters litter the streets, urging people to join the pack or submit to it. Then you see them. Fennecs start to emerge from the dark, trash-filled alleyways. They glare at you menacingly. They know who you are and why you are here, and they are not going to go easy on you. Get ready for the fight of your life!
