INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Tribe Game', 'The Tribe Game is a story-driven video game where the player gets to create their own custom character and step into the world of The Tribe. In this RPG (role-playing game) they will interact with many iconic characters and explore familiar places from The Tribe TV series. There are quests to be accomplished, profession skills to level up, items and resources to be found, battles to be won, and adventures to unfold… as the player tries to survive in a post-apocalyptic world and to keep their (and their tribe’s) dreams alive.' FROM games WHERE igdb_id = 191292 ON CONFLICT (game_id, language_code) DO NOTHING;
