INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jake Everest: Wakanga The Unseen Civilization', 'Renowned archaeologist Jake Everest has found that recovering stolen and lost artifacts is a rewarding use of his skill and expertise. His good deeds have earned him a fantastic reputation worldwide, and many have called upon him for help. His latest case takes Jake to a small mining colony in Papua where a mysterious plane crash nearby has caused unrest in the workers and is disrupting operations. Can you help Jake unravel the mystery and return peace to this small civilization? Adventure awaits!' FROM games WHERE igdb_id = 258879 ON CONFLICT (game_id, language_code) DO NOTHING;
