INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('survive-on-raft', 125851, '2022-01-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5aus.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1e05.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Survive on Raft', 'You survive in a terrible plane crash and now you are out of civilization. Around the endless ocean, exhausting sun and hungry sharks. There is only one thing left for you - to survive at any cost. To do this, you need to collect resources, improve the raft and build your shelter right on the raft. Remember that thirst and hunger are not the only dangers. Make sure the hungry shark doesn''t destroy your raft! Survival Simulator Watch for indicators of health, hunger and thirst. Otherwise your adventure on the raft will quickly end! Explore the recipe for crafting! Catch fish, grow vegetables and get water — do everything to survive! Create building materials, clothes, weapons, chests and other things necessary for survival. Explore the islands! Travel to the islands and discover new lands! Get resources! Use the hook to catch the necessary resources: debris, algae, boxes and others. They will be useful to you for survival! Craft and build! Spread, equip and protect the raft. Build a real shelter that will allow you to last as long as possible! Сreative Mode! A mode for real architects who want to make their dreams come true!' FROM games WHERE igdb_id = 125851 ON CONFLICT (game_id, language_code) DO NOTHING;
