INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('lone-tower-roguelite-defense', 255805, '2022-12-31', NULL, NULL, NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lone Tower Roguelite Defense', 'Lone Tower is an idle tower defense game with a unique twist of Idle and Roguelike features. Lone Tower is inspired by games such as Oregon Trail and The Tower, it is an incremental tower defense game where you control and upgrade a single tower and have to survive as many days as possible. There is farming, card collecting, mining, and plenty of repairs to do in order to survive each day! Defend your tower until its destroyed, earn coins & gems to unlock permanent upgrades, then give it another try! Build the perfect tower for defense against fantasy creatures and foes!' FROM games WHERE igdb_id = 255805 ON CONFLICT (game_id, language_code) DO NOTHING;
