INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Astroblaster', 'An arcade-style 2D top-down space shooter. Blow up space rocks and space pirates for as long as you can. You''ll also need to maximize a delicately-balanced economy of resources. Keep trying to out-do yourself! Five boss ships will break in at various points to make life difficult.' FROM games WHERE igdb_id = 207777 ON CONFLICT (game_id, language_code) DO NOTHING;
