INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ys Online: The Ark of Napishtim', 'Ys Online: The Ark of Napishtim is licensed and adapted from the sixth generation of the legendary Japanese franchise, the Ys series. The game, supervised by Falcom, inherits the soul of popular JRPG adventures. While revitalizing the original plot, a premier VA lineup was added to dub the entire story, crafting a richer and more refined experience. In the game, adventurers will accompany Adol to the Great Vortex of Canaan to meet the mysterious Rehdan Sisters and together explore the Ruins of the Winged One Civilization.' FROM games WHERE igdb_id = 214085 ON CONFLICT (game_id, language_code) DO NOTHING;
