INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Toy Factory Across the Street', 'Francesca, a brilliant young transgender journalist, goes back to the house where she grew up to celebrate the birthday of her father. Unfortunately for Francesca, there''s an abandoned toy factory across the street where many people have died or have been reported missing, and strange phenomena can be witnessed at night. She has always dreaded that place, and now what was supposed to be a nice celebration will turn out to be a night full of horrors beyond human comprehension...INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 225820 AND ge.slug = 'indie' ON CONFLICT DO NOTHING;
