INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'I Expect You to Die: Home Sweet Home', 'Become a secret agent in your own living room in this short mixed reality mini-mission. You have been smuggled out of a top-secret medical facility to recover in the comfort of your home. Fitted with your new ocular implant, you will decipher puzzles, dodge dangerous threats, fight robotic hornets, and use spy gadgets galore. Dr. Zor has set a trap - right in your home! It is up to you to thwart those plans and save the day.' FROM games WHERE igdb_id = 223146 ON CONFLICT (game_id, language_code) DO NOTHING;
